import * as THREE from 'three';
const TYPES=['equipment-id','warning-pinch','electrical','flow','grease','shipping','fragile','capacity'];
export function makeStickerAtlas(){const canvas=document.createElement('canvas');canvas.width=1024;canvas.height=512;const c=canvas.getContext('2d');
 TYPES.forEach((type,index)=>{const x=index%4*256,y=Math.floor(index/4)*256;c.save();c.translate(x,y);c.fillStyle=type==='warning-pinch'||type==='electrical'?'#f3cb24':type==='flow'?'#197652':'#e8e7dd';c.fillRect(6,6,244,244);c.strokeStyle='#162126';c.lineWidth=5;c.strokeRect(8,8,240,240);c.textAlign='center';c.textBaseline='middle';c.fillStyle='#142127';c.font='bold 25px Arial';
 if(type==='equipment-id'){c.fillStyle='#1a363f';c.fillRect(10,10,236,58);c.fillStyle='#fff';c.font='bold 22px Arial';c.fillText('SMART-TWIN',128,31);c.font='14px Arial';c.fillText('Simulator',128,54);c.fillStyle='#142127';c.font='bold 20px Arial';c.fillText('INDUSTRIAL EQUIPMENT',128,91);c.font='17px Arial';c.fillText('MODEL · HX SERIES',128,123);c.fillText('INSPECCIÓN / SERVICIO',128,153);for(let i=0;i<47;i++){c.fillRect(22+i*4.5,179,1+(i*7%3),38);}c.font='12px Arial';c.fillText('SIMULACIÓN · ID EN EL HMI',128,231);}
 if(type==='warning-pinch'){triangle(c);c.fillRect(73,142,110,17);c.beginPath();c.moveTo(112,101);c.lineTo(126,139);c.lineTo(146,134);c.lineTo(138,98);c.lineTo(125,88);c.closePath();c.fill();c.font='bold 19px Arial';c.fillText('RIESGO DE ATRAPAMIENTO',128,207);c.font='14px Arial';c.fillText('MANTENER LAS MANOS FUERA',128,230);}
 if(type==='electrical'){triangle(c);c.beginPath();c.moveTo(141,61);c.lineTo(103,123);c.lineTo(128,123);c.lineTo(113,165);c.lineTo(159,103);c.lineTo(134,103);c.closePath();c.fill();c.font='bold 22px Arial';c.fillText('RIESGO ELÉCTRICO',128,207);c.font='14px Arial';c.fillText('DESCONECTAR PARA SERVICIO',128,230);}
 if(type==='flow'){c.fillStyle='#fff';c.beginPath();c.moveTo(57,90);c.lineTo(143,90);c.lineTo(143,54);c.lineTo(207,121);c.lineTo(143,186);c.lineTo(143,151);c.lineTo(57,151);c.closePath();c.fill();c.font='bold 25px Arial';c.fillText('FLUJO / FLOW',128,218);}
 if(type==='grease'){c.beginPath();c.moveTo(127,44);c.bezierCurveTo(71,107,77,149,126,157);c.bezierCurveTo(174,150,183,105,127,44);c.fill();c.font='bold 23px Arial';c.fillText('LUBRICACIÓN',128,197);c.font='16px Arial';c.fillText('REVISIÓN PERIÓDICA',128,224);}
 if(type==='shipping'){c.font='bold 26px Arial';c.fillText('TRAZABILIDAD',128,34);for(let i=0;i<45;i++)c.fillRect(23+i*4.7,63,1+(i*3%4),96);c.font='20px Arial';c.fillText('SKU · INDUSTRIAL',128,186);c.font='14px Arial';c.fillText('LOTE Y CONTENIDO EN EL HMI',128,219);}
 if(type==='fragile'){c.strokeStyle='#142127';c.lineWidth=8;c.beginPath();c.moveTo(85,46);c.lineTo(171,46);c.lineTo(156,105);c.quadraticCurveTo(128,143,99,104);c.closePath();c.moveTo(128,124);c.lineTo(128,173);c.moveTo(100,176);c.lineTo(157,176);c.stroke();c.font='bold 24px Arial';c.fillText('FRÁGIL / FRAGILE',128,218);}
 if(type==='capacity'){c.font='bold 24px Arial';c.fillText('CARGA NOMINAL',128,41);c.fillRect(56,88,143,65);c.fillStyle='#e8e7dd';c.font='bold 37px Arial';c.fillText('kg',128,122);c.fillStyle='#142127';c.font='17px Arial';c.fillText('CAPACIDAD EN EL HMI',128,187);c.font='12px Arial';c.fillText('CONSULTAR ALTURA Y CENTRO',128,222);}
 c.restore();});
 const texture=new THREE.CanvasTexture(canvas);texture.name='Etiquetas industriales SMART-TWIN Simulator · atlas';texture.encoding=THREE.sRGBEncoding;texture.generateMipmaps=true;texture.minFilter=THREE.LinearMipmapLinearFilter;texture.needsUpdate=true;texture.userData={sharedIndustrialTexture:true};return texture;}
function triangle(c){c.beginPath();c.moveTo(128,39);c.lineTo(208,173);c.lineTo(48,173);c.closePath();c.lineWidth=7;c.strokeStyle='#142127';c.stroke();}
export function stickerTile(id){const index=Math.max(0,TYPES.indexOf(id));return {u:index%4/4,v:1-(Math.floor(index/4)+1)/2,w:1/4,h:1/2};}
